public static void check(Solution solution) {
    assert Arrays.equals(solution.validateBinaryTreeNodes(2, new int[]{1,0}, new int[]{-1,-1}), False);
    assert Arrays.equals(solution.validateBinaryTreeNodes(3, new int[]{1,-1,-1}, new int[]{2,-1,-1}), True);
    assert Arrays.equals(solution.validateBinaryTreeNodes(3, new int[]{1,0,-1}, new int[]{-1,-1,-1}), False);
    assert Arrays.equals(solution.validateBinaryTreeNodes(1, new int[]{-1}, new int[]{-1}), True);
    assert Arrays.equals(solution.validateBinaryTreeNodes(4, new int[]{1,-1,3,-1}, new int[]{2,-1,-1,-1}), True);
    assert Arrays.equals(solution.validateBinaryTreeNodes(4, new int[]{1,-1,3,-1}, new int[]{2,3,-1,-1}), False);
